const browser=function browser(){const $=id=>document.getElementById(id);const money=n=>n.toLocaleString('en-IN',{style:'currency',currency:'INR'});$('go').onclick=async()=>{try{const k=document.body.dataset.kind,o=$('out');if(k==='words'){const t=$('text').value;o.textContent='Words: '+(t.trim()?t.trim().split(/\s+/).length:0)+'\nCharacters: '+Array.from(t).length;return}if(k==='json'){o.textContent=JSON.stringify(JSON.parse($('text').value),null,2);return}if(k==='resize'||k==='compress'){const f=$('file').files[0];if(!f)throw Error('Choose an image');const im=await createImageBitmap(f),c=document.createElement('canvas');c.width=k==='resize'?Number($('w').value):im.width;c.height=k==='resize'?Number($('h').value):im.height;if(c.width<1||c.height<1||c.width*c.height>25000000)throw Error('Invalid dimensions');const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);im.close();const q=k==='compress'?Number($('q').value):100;if(q<1||q>100)throw Error('Quality must be 1–100');const blob=await new Promise(r=>c.toBlob(r,k==='compress'?'image/jpeg':'image/png',q/100));if(!blob)throw Error('Conversion failed');const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=k==='compress'?'compressed.jpg':'resized.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);o.textContent='Output: '+Math.round(blob.size/1024)+' KB';return}const v=[...document.querySelectorAll('input[type=number]')].map(e=>e.value===''?NaN:Number(e.value));if(v.some(n=>!Number.isFinite(n)||(n<0&&k!=='temp')))throw Error('Enter valid non-negative numbers');const [a,b,c]=v;let r=b/1200,n=c*12;const fmt=x=>Number(x.toPrecision(10)).toLocaleString('en-US',{maximumFractionDigits:8});const show=(...pairs)=>o.textContent=pairs.map(([l,x])=>l+': '+fmt(x)).join('\n');if(k==='bankinterest'){const d=v[3];if(!Number.isInteger(d)||d<1||d>365||c>100)throw Error('Enter 1–365 compounding periods and up to 100 years');const total=a*Math.pow(1+b/100/d,c*d);show(['Interest earned',total-a],['Maturity amount',total])}if(k==='savingsinterest'){const interest=a*b/100*c/365;show(['Interest earned',interest],['Total balance',a+interest])}if(k==='rdinterest'){if(!Number.isInteger(c)||c<1||c>1200)throw Error('Enter 1–1200 months');const total=r?a*Math.expm1(c*Math.log1p(r))/r:a*c;show(['Total deposits',a*c],['Interest earned',total-a*c],['Maturity amount',total])}if(k==='loan'){if(!Number.isInteger(c)||c<1||c>1200)throw Error('Enter 1–1200 months');const m=r?a*r/(-Math.expm1(-c*Math.log1p(r))):a/c;show(['Monthly payment',m],['Total interest',m*c-a],['Total repayment',m*c])}if(k==='bmi'){if(a<=0||b<=0)throw Error('Enter positive height and weight');show(['BMI',a/(b/100)**2])}if(k==='temp'){if(a< -273.15)throw Error('Below absolute zero');show(['Fahrenheit',a*9/5+32],['Kelvin',a+273.15])}if(k==='length')show(['Feet',a/0.3048],['Inches',a/0.0254],['Kilometers',a/1000]);if(k==='weight')show(['Pounds',a/0.45359237],['Ounces',a/0.028349523125],['Grams',a*1000]);if(k==='speed')show(['mph',a/1.609344],['m/s',a/3.6]);if(k==='area')show(['Square feet',a/0.09290304],['Hectares',a/10000],['Acres',a/4046.8564224]);if(k==='volume')show(['Milliliters',a*1000],['US gallons',a/3.785411784]);if(k==='tip'){if(!Number.isInteger(c)||c<1)throw Error('Enter a positive number of people');show(['Tip',a*b/100],['Total',a*(1+b/100)],['Per person',a*(1+b/100)/c])}if(k==='change'){if(a===0)throw Error('Original value must be positive');show(['Change %',(b-a)/a*100])}if(k==='tax')show(['Tax',a*b/100],['Total',a*(1+b/100)]);if(k==='fuel'){if(a<=0||b<=0)throw Error('Enter positive distance and fuel');show(['L/100 km',b/a*100],['US mpg',a/1.609344/(b/3.785411784)])}if(k==='time')show(['Minutes',a*60],['Seconds',a*3600],['Days',a/24]);if(k==='average')show(['Average',(a+b+c)/3]);if(k==='gst')o.textContent='GST: '+money(a*b/100)+' | Total: '+money(a*(1+b/100))+' | Base if inclusive: '+money(a/(1+b/100));if(k==='emi'){if(!Number.isInteger(c)||c<1||c>1200)throw Error('Enter 1–1200 months');const m=r?a*r/(1-Math.pow(1+r,-c)):a/c;o.textContent='EMI: '+money(m)+' | Interest: '+money(m*c-a)}if(k==='sip'){if(c>100)throw Error('Maximum 100 years');o.textContent='Estimated value: '+money(r?a*Math.expm1(n*Math.log1p(r))/r:a*n)+' | Invested: '+money(a*n)}if(k==='fd'){if(c>100)throw Error('Maximum 100 years');o.textContent='Maturity: '+money(a*Math.pow(1+b/400,c*4))}if(k==='simple')o.textContent='Interest: '+money(a*b*c/100)+' | Total: '+money(a+a*b*c/100);if(k==='compound')o.textContent='Final value: '+money(a*Math.pow(1+b/100,c));if(k==='margin'){if(a<=0)throw Error('Selling price must be positive');o.textContent='Profit: '+money(a-b)+' | Margin: '+((a-b)/a*100).toFixed(2)+'%'}if(k==='cagr'){if(a<=0||c<=0)throw Error('Initial value and years must be positive');o.textContent='CAGR: '+((Math.pow(b/a,1/c)-1)*100).toFixed(2)+'%'}if(k==='salary')o.textContent='Estimated take home: '+money(a-b);if(k==='percent')o.textContent=String(a*b/100);if(k==='discount'){if(b>100)throw Error('Maximum 100%');o.textContent='Sale price: '+money(a*(1-b/100))+' | Savings: '+money(a*b/100)}}catch(e){$('out').textContent=e.message}finally{if($('out').textContent){$('out').scrollIntoView({block:'nearest',behavior:'smooth'});$('out').focus({preventScroll:true});}}};document.querySelectorAll('input[type=number]').forEach(el=>el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('go').click()}}));};

