const lessonNav='<a href="/learn/sap-s4hana/">SAP S/4HANA Modules</a><nav style="display:flex;flex-direction:column;gap:6px">'+lessons.map(([slug,title])=>'<a href="/learn/'+slug+'/">'+title+' Tutorial</a>').join('')+'</nav>';
page('learn','Learn Programming and Business Software','Free beginner tutorials for HTML, CSS, JavaScript, SQL, Python, Excel and SAP Business One.','<section class="panel">'+lessonNav+'</section>');
for(const [slug,title,desc,example] of lessons){const runnable=['html','css','javascript'].includes(slug);page('learn/'+slug,title+' Tutorial',desc,'<div class="lesson-layout"><aside>'+lessonNav+'</aside><article><h2>Introduction to '+title+'</h2><p>'+desc+'</p><h2>Example</h2><pre>'+esc(example)+'</pre>'+(runnable?'<label>Try it yourself<textarea id="editor" rows="8">'+esc(example)+'</textarea></label><button id="run" type="button">Run example</button><iframe id="preview" title="Example output" sandbox="allow-scripts" style="width:100%;height:180px;background:white;border:1px solid #cbd5e1;margin-top:16px"></iframe><script>document.getElementById("run").onclick=()=>{document.getElementById("preview").srcdoc=document.getElementById("editor").value}</script>':'<p>Practice this example in your own '+title+' environment. This page does not execute it.</p>')+'<p><a href="/learn/">All tutorials</a></p></article></div>');}
const sapModules=[["fi","FI – Financial Accounting","General ledger, accounts payable, accounts receivable, asset accounting and closing.","Post a supplier invoice: debit expense or inventory clearing as applicable, credit supplier."],["co","CO – Controlling","Cost centers, profit centers, internal orders, product costing and profitability analysis.","Assign an expense to a cost center and review actual versus plan."],["mm","MM – Materials Management","Purchasing, inventory management, material master and invoice verification.","Purchase requisition → purchase order → goods receipt → invoice verification."],["sd","SD – Sales and Distribution","Sales orders, pricing, delivery, billing and credit management.","Sales order → outbound delivery → goods issue → billing."],["pp","PP – Production Planning","BOM, routing, MRP, production orders and confirmations.","Run MRP, create a production order, issue components and receive finished goods."],["qm","QM – Quality Management","Inspection plans, inspection lots, results and usage decisions.","Record inspection results for a goods receipt and make a usage decision."],["pm","Asset Management (PM/EAM)","Equipment, functional locations, notifications and maintenance orders.","Create a maintenance notification and plan corrective maintenance."],["ewm","Extended Warehouse Management","Inbound and outbound warehouse processes, storage bins and warehouse tasks.","Receive goods, create a putaway task and confirm the destination bin."],["tm","Transportation Management","Freight planning, freight orders and settlement.","Plan transportation for outbound deliveries and create a freight order."],["ps","Project System","WBS elements, networks, budgeting and project settlement.","Create a WBS structure and assign project costs."],["aa","Asset Accounting (FI-AA)","Asset acquisition, depreciation, transfers and retirement.","Acquire an asset and review planned depreciation."],["treasury","Treasury and Risk Management","Cash management, financial instruments and risk analysis.","Review cash positions and forecast liquidity."],["gr","Group Reporting","Financial consolidation, intercompany elimination and group reporting.","Prepare consolidation data and eliminate intercompany balances."],["service","Service Management","Service contracts, service orders, execution and billing.","Create a service order and confirm work performed."],["aATP","Advanced Available-to-Promise","Product availability checks, allocation and backorder processing.","Check requested delivery quantities against available supply."],["mdg","Master Data Governance","Governance workflows, validation and master data quality.","Submit a business partner change request for approval."],["fiori","SAP Fiori","Role-based applications, launchpad and user experience.","Locate an authorized business app and review its filters."],["abap","ABAP and Extensibility","ABAP development, CDS views, RAP and clean-core extensions.","Define a read-only CDS view in an authorized development environment."],["basis","Basis and Security","System administration, authorizations, transports and monitoring.","Review a role assignment and transport request in a test system."],["analytics","Embedded Analytics","CDS analytical queries, KPIs and operational reporting.","Review a sales or inventory analytical report."],["hcm","HR and SuccessFactors Integration","Employee data and integration with HR solutions; deployment scope varies.","Review employee master integration requirements."],["grc","Governance, Risk and Compliance","Access risk analysis, segregation of duties and controls; separate solutions may be required.","Identify conflicting purchasing and payment permissions."]];
const sapLinks='<nav>'+sapModules.map(([slug,title])=>'<a href="/learn/sap-s4hana/'+slug.toLowerCase()+'/">'+esc(title)+'</a>').join('')+'</nav>';
page('learn/sap-s4hana','SAP S/4HANA Tutorials','Learn SAP S/4HANA functional modules, technical topics and integrated business processes.','<p>Scope and app availability vary by edition, release and license. These original introductory lessons are not official SAP training.</p><section class="panel">'+sapLinks+'</section>');
for(const [slug,title,desc,example] of sapModules){page('learn/sap-s4hana/'+slug.toLowerCase(),'SAP S/4HANA '+title,desc,'<p><a href="/learn/sap-s4hana/">All SAP S/4HANA modules</a></p><section class="panel"><h2>Overview</h2><p>'+esc(desc)+'</p><h2>Practical exercise</h2><p>'+esc(example)+'</p><p>Practice only in an authorized training system. Exact applications and configuration depend on your edition.</p></section>'+sapLinks);}
const b1Topics=[["query-manager","SQL Query Manager","Open Tools → Queries → Query Generator or Query Manager (menu availability depends on authorization). Create a query, execute it, save it in a category and assign authorized users. Use [%0] and [%1] for date parameters.","SELECT DocNum, DocDate, CardCode, CardName, DocTotal FROM ORDR WHERE DocDate >= CONVERT(date, '[%0]') AND DocDate <= CONVERT(date, '[%1]') AND CANCELED = 'N';"],["sales","Sales and A/R","Quotation → Sales Order → Delivery → A/R Invoice → Incoming Payment. Delivery normally debits COGS and credits inventory; invoice debits customer and credits revenue and output tax.","SELECT H.DocNum,H.DocDate,H.CardName,L.ItemCode,L.Quantity,L.LineTotal FROM OINV H JOIN INV1 L ON H.DocEntry=L.DocEntry WHERE H.CANCELED='N';"],["purchase","Purchasing and A/P","Purchase Request → Purchase Order → GRPO → A/P Invoice → Outgoing Payment. Under perpetual inventory, GRPO normally debits inventory and credits allocation; invoice clears allocation and credits vendor, subject to tax and differences.","SELECT H.DocNum,H.CardName,L.ItemCode,L.OpenQty FROM OPOR H JOIN POR1 L ON H.DocEntry=L.DocEntry WHERE H.CANCELED='N' AND L.LineStatus='O';"],["inventory","Inventory Management","Item master, warehouses, stock transfers, goods receipts and issues. OnHand is physical stock; committed and ordered quantities affect availability.","SELECT I.ItemCode,I.ItemName,W.WhsCode,W.OnHand,W.IsCommited,W.OnOrder FROM OITM I JOIN OITW W ON I.ItemCode=W.ItemCode;"],["finance","Financial Accounting","Journal entries, chart of accounts, reconciliations, receivables and payables. Each journal entry balances debits and credits.","SELECT H.TransId,H.RefDate,L.Account,L.ShortName,L.Debit,L.Credit FROM OJDT H JOIN JDT1 L ON H.TransId=L.TransId;"],["production","Production and MRP","BOM → Production Order → Issue for Production → Receipt from Production → Close. Actual WIP and finished goods postings depend on valuation and configuration.","SELECT H.DocNum,H.ItemCode,H.PlannedQty,H.CmpltQty,H.Status FROM OWOR H WHERE H.Status IN ('P','R');"],["business-partners","Business Partners","Maintain customer and vendor master data, payment terms and addresses.","SELECT CardCode,CardName,CardType,Balance FROM OCRD WHERE CardType IN ('C','S');"],["banking","Banking and Payments","Incoming payments normally debit bank and credit customer; outgoing payments debit vendor and credit bank. Reconciliation matches open transactions.","SELECT DocNum,DocDate,CardCode,DocTotal FROM OVPM WHERE Canceled='N';"],["service","Service Management","Service calls, equipment cards and service contracts.","SELECT callID,customer,subject,status FROM OSCL;"],["fixed-assets","Fixed Assets","Asset acquisition, depreciation and retirement. Depreciation normally debits depreciation expense and credits accumulated depreciation.","SELECT ItemCode,ItemName FROM OITM WHERE AssetItem='Y';"],["crm","CRM and Opportunities","Track prospects, activities and sales opportunities.","SELECT CardCode,CardName FROM OCRD WHERE CardType='L';"],["fms","Formatted Search (FMS)","Assign a saved query to a field using user-defined values. Form references depend on the actual form and item IDs; verify using System Information.","SELECT ItemName FROM OITM WHERE ItemCode = $[$38.1.0];"],["transaction-notification","Transaction Notification","SBO_SP_TransactionNotification validates transactions before commit. Test changes in a sandbox; never modify SAP business tables directly. Example below is a read-only diagnostic, not a complete stored procedure.","SELECT DocEntry,DocNum,CardCode FROM ORDR WHERE CardCode IS NULL;"],["crystal-reports","Crystal Reports","Create reports using supported data connections, parameters and layouts. Test the report against a non-production database.","SELECT H.DocNum,H.CardName,L.Dscription,L.Quantity FROM OQUT H JOIN QUT1 L ON H.DocEntry=L.DocEntry;"],["query-library","SQL Query Library","Use read-only SELECT queries. Avoid direct UPDATE, INSERT or DELETE against SAP application tables. Validate results against standard reports.","SELECT T0.DocNum,T0.DocDate,T0.CardName,T1.ItemCode,T1.Quantity,T1.LineTotal FROM OQUT T0 INNER JOIN QUT1 T1 ON T0.DocEntry=T1.DocEntry WHERE T0.CANCELED='N';"],["administration","Administration and Authorizations","Company settings, users, roles, approvals, numbering series and backup coordination. Use authorized administration screens.","SELECT Series,SeriesName,ObjectCode FROM NNM1;"]];
const b1Nav='<a href="/learn/sap-b1/sql-practice/">SQL Practice Playground</a><nav style="display:flex;flex-direction:column;gap:6px">'+b1Topics.map(([slug,title])=>'<a href="/learn/sap-b1/'+slug+'/">'+esc(title)+'</a>').join('')+'</nav>';
page('learn/sap-b1','SAP Business One Training','SAP Business One 10.0 SQL Server tutorials, document flows, accounting and Query Manager.','<div class="lesson-layout"><aside>'+b1Nav+'</aside><article><h2>Start learning SAP Business One</h2><p>Explore functional modules and technical reporting with practical examples. Use a training database and authorized read-only access.</p><p><a href="/learn/sap-b1/query-manager/">Start SQL Query Manager</a></p></article></div>');
for(const [slug,title,desc,query] of b1Topics){page('learn/sap-b1/'+slug,'SAP B1 '+title,desc,'<div class="lesson-layout"><aside>'+b1Nav+'</aside><article><h2>'+esc(title)+'</h2><p>'+esc(desc)+'</p><h2>SQL Server example</h2><pre id="sql-example">'+esc(query)+'</pre><button type="button" id="copy-sql">Copy SQL query</button><p id="copy-status" role="status"></p><script>document.getElementById("copy-sql").onclick=async()=>{try{await navigator.clipboard.writeText(document.getElementById("sql-example").textContent);document.getElementById("copy-status").textContent="Query copied"}catch(e){document.getElementById("copy-status").textContent="Select and copy the query manually."}}</script><h2>Practice</h2><p>Run the example in the appropriate authorized SAP B1 environment. Query Manager placeholders and FMS references are SAP-specific and do not run unchanged in SSMS. Results depend on your company data and configuration.</p></article></div>');}
page('learn/sap-b1/sql-practice','SAP B1 SQL Practice Playground','Practice SELECT queries with sample SAP Business One tables.',"<div class=\"lesson-layout\"><aside><h2>Practice tables</h2><p>OCRD · OITM · ORDR · RDR1 · OQUT · QUT1 · ODLN · DLN1 · OINV · INV1 · ORIN · RIN1 · OPRQ · PRQ1 · OPOR · POR1 · OPDN · PDN1 · OPCH · PCH1 · ORPC · RPC1 · OIGN · IGN1 · OIGE · IGE1 · OWTR · WTR1 · ODRF · DRF1 · OWHS · OITW · OITB · OACT · OJDT · JDT1 · ORCT · RCT2 · OVPM · VPM2 · OWOR · WOR1 · OITT · ITT1 · OSLP · OHEM · OCTG · ORTT · OITR · ITR1 · NNM1 · OSCL</p><p>OCRD – Business partners</p><p>OITM – Items</p><p>ORDR – Sales orders</p><p>RDR1 – Sales order lines</p><a href=\"/learn/sap-b1/query-manager/\">Query Manager tutorial</a></aside><article><p>Run real SQL against fictional SAP-style sample data. This browser sandbox uses SQLite, not Microsoft SQL Server. T-SQL functions and SAP parameters may not work.</p><label>Browse sample table<select id=\"sql-table\" style=\"width:100%;padding:12px\"><option value=\"\">Choose table</option></select></label><label>SQL editor<textarea id=\"sql-editor\" rows=\"9\">SELECT * FROM ORDR;</textarea></label><button id=\"sql-run\" disabled>Run SQL</button><p id=\"sql-status\" role=\"status\">Loading practice database...</p><div id=\"sql-output\" style=\"overflow:auto\"></div><h2>Practice exercises</h2><pre>SELECT * FROM OCRD;\\nSELECT ItemCode, OnHand FROM OITM;\\nSELECT H.DocNum,L.ItemCode,L.Quantity FROM ORDR H JOIN RDR1 L ON H.DocEntry=L.DocEntry;\\nSELECT SUM(DocTotal) FROM ORDR;</pre></article></div><script src=\"https://cdn.jsdelivr.net/npm/sql.js@1.13.0/dist/sql-wasm.js\"></script><script type=\"module\">const status=document.getElementById('sql-status'),editor=document.getElementById('sql-editor'),out=document.getElementById('sql-output'),run=document.getElementById('sql-run');let db;try{const SQL=await initSqlJs({locateFile:f=>'https://cdn.jsdelivr.net/npm/sql.js@1.13.0/dist/'+f});db=new SQL.Database();db.run(\"CREATE TABLE OCRD(CardCode TEXT,CardName TEXT,CardType TEXT); INSERT INTO OCRD VALUES ('C001','Alpha Labs','C'),('C002','Beta Pharma','C'),('V001','Global Supplies','S'); CREATE TABLE OITM(ItemCode TEXT,ItemName TEXT,OnHand REAL); INSERT INTO OITM VALUES ('I001','Sample A',100),('I002','Sample B',50); CREATE TABLE ORDR(DocEntry INTEGER,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,CANCELED TEXT); INSERT INTO ORDR VALUES (1,1001,'2026-11-01','C001','Alpha Labs',1500,'N'),(2,1002,'2026-11-02','C002','Beta Pharma',2500,'N'); CREATE TABLE RDR1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Quantity REAL,LineTotal REAL); INSERT INTO RDR1 VALUES (1,0,'I001',3,1500),(2,0,'I002',5,2500);\");db.run(\"CREATE TABLE OQUT(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OQUT VALUES(1,2301,'2026-11-03','C001','Alpha Labs',1500,'O','N','23'); CREATE TABLE QUT1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO QUT1 VALUES(1,0,'I001','Sample A',3,500,1500,3,'O','01',-1,-1,-1); CREATE TABLE ODLN(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO ODLN VALUES(1,1501,'2026-11-03','C001','Alpha Labs',1500,'O','N','15'); CREATE TABLE DLN1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO DLN1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',17,1,0); CREATE TABLE OINV(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OINV VALUES(1,1301,'2026-11-03','C001','Alpha Labs',1500,'O','N','13'); CREATE TABLE INV1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO INV1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',15,1,0); CREATE TABLE ORIN(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO ORIN VALUES(1,1401,'2026-11-03','C001','Alpha Labs',1500,'O','N','14'); CREATE TABLE RIN1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO RIN1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',13,1,0); CREATE TABLE OPRQ(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OPRQ VALUES(1,9001,'2026-11-03','V001','Global Supplies',1500,'O','N','1470000113'); CREATE TABLE PRQ1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO PRQ1 VALUES(1,0,'I001','Sample A',3,500,1500,3,'O','01',-1,-1,-1); CREATE TABLE OPOR(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OPOR VALUES(1,2201,'2026-11-03','V001','Global Supplies',1500,'O','N','22'); CREATE TABLE POR1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO POR1 VALUES(1,0,'I001','Sample A',3,500,1500,3,'O','01',1470000113,1,0); CREATE TABLE OPDN(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OPDN VALUES(1,2001,'2026-11-03','V001','Global Supplies',1500,'O','N','20'); CREATE TABLE PDN1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO PDN1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',22,1,0); CREATE TABLE OPCH(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OPCH VALUES(1,1801,'2026-11-03','V001','Global Supplies',1500,'O','N','18'); CREATE TABLE PCH1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO PCH1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',20,1,0); CREATE TABLE ORPC(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO ORPC VALUES(1,1901,'2026-11-03','V001','Global Supplies',1500,'O','N','19'); CREATE TABLE RPC1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO RPC1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',18,1,0); CREATE TABLE OIGN(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OIGN VALUES(1,5901,'2026-11-03','V001','Global Supplies',1500,'O','N','59'); CREATE TABLE IGN1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO IGN1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',-1,-1,-1); CREATE TABLE OIGE(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OIGE VALUES(1,6001,'2026-11-03','V001','Global Supplies',1500,'O','N','60'); CREATE TABLE IGE1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO IGE1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',-1,-1,-1); CREATE TABLE OWTR(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OWTR VALUES(1,6701,'2026-11-03','V001','Global Supplies',1500,'O','N','67'); CREATE TABLE WTR1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO WTR1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',-1,-1,-1); CREATE TABLE ODRF(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO ODRF VALUES(1,11201,'2026-11-03','V001','Global Supplies',1500,'O','N','112'); CREATE TABLE DRF1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO DRF1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',-1,-1,-1); CREATE TABLE OWHS(WhsCode TEXT,WhsName TEXT); INSERT INTO OWHS VALUES('01','Main Warehouse'); CREATE TABLE OITW(ItemCode TEXT,WhsCode TEXT,OnHand REAL,IsCommited REAL,OnOrder REAL); INSERT INTO OITW VALUES('I001','01',100,3,10); CREATE TABLE OITB(ItmsGrpCod INTEGER,ItmsGrpNam TEXT); INSERT INTO OITB VALUES(100,'Sample Items'); CREATE TABLE OACT(AcctCode TEXT,AcctName TEXT); INSERT INTO OACT VALUES('110000','Bank'); CREATE TABLE OJDT(TransId INTEGER,RefDate TEXT,Memo TEXT); INSERT INTO OJDT VALUES(1,'2026-11-03','Sample invoice'); CREATE TABLE JDT1(TransId INTEGER,Line_ID INTEGER,Account TEXT,ShortName TEXT,Debit REAL,Credit REAL); INSERT INTO JDT1 VALUES(1,0,'110000','110000',1500,0),(1,1,'400000','400000',0,1500); CREATE TABLE ORCT(DocEntry INTEGER,DocNum INTEGER,CardCode TEXT,DocTotal REAL,Canceled TEXT); INSERT INTO ORCT VALUES(1,5001,'C001',1500,'N'); CREATE TABLE RCT2(DocNum INTEGER,DocEntry INTEGER,InvType INTEGER,SumApplied REAL); INSERT INTO RCT2 VALUES(1,1,13,1500); CREATE TABLE OVPM(DocEntry INTEGER,DocNum INTEGER,CardCode TEXT,DocTotal REAL,Canceled TEXT); INSERT INTO OVPM VALUES(1,6001,'V001',1500,'N'); CREATE TABLE VPM2(DocNum INTEGER,DocEntry INTEGER,InvType INTEGER,SumApplied REAL); INSERT INTO VPM2 VALUES(1,1,18,1500); CREATE TABLE OWOR(DocEntry INTEGER,DocNum INTEGER,ItemCode TEXT,PlannedQty REAL,CmpltQty REAL,Status TEXT); INSERT INTO OWOR VALUES(1,7001,'I002',10,5,'R'); CREATE TABLE WOR1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,PlannedQty REAL,IssuedQty REAL); INSERT INTO WOR1 VALUES(1,0,'I001',20,10); CREATE TABLE OITT(Code TEXT,Name TEXT,Quantity REAL); INSERT INTO OITT VALUES('I002','Sample B',1); CREATE TABLE ITT1(Father TEXT,Code TEXT,Quantity REAL); INSERT INTO ITT1 VALUES('I002','I001',2); CREATE TABLE OSLP(SlpCode INTEGER,SlpName TEXT); INSERT INTO OSLP VALUES(1,'Demo Salesperson'); CREATE TABLE OHEM(empID INTEGER,firstName TEXT,lastName TEXT); INSERT INTO OHEM VALUES(1,'Demo','Employee'); CREATE TABLE OCTG(GroupNum INTEGER,PymntGroup TEXT); INSERT INTO OCTG VALUES(1,'Net 30'); CREATE TABLE ORTT(RateDate TEXT,Currency TEXT,Rate REAL); INSERT INTO ORTT VALUES('2026-11-03','USD',85); CREATE TABLE OITR(ReconNum INTEGER,ReconDate TEXT,Canceled TEXT); INSERT INTO OITR VALUES(1,'2026-11-03','N'); CREATE TABLE ITR1(ReconNum INTEGER,TransId INTEGER,SrcObjTyp INTEGER,SrcObjAbs INTEGER,ReconSum REAL); INSERT INTO ITR1 VALUES(1,1,13,1,1500); CREATE TABLE NNM1(Series INTEGER,SeriesName TEXT,ObjectCode TEXT); INSERT INTO NNM1 VALUES(1,'Demo','17'); CREATE TABLE OSCL(callID INTEGER,customer TEXT,subject TEXT,status INTEGER); INSERT INTO OSCL VALUES(1,'C001','Sample service call',-3); ALTER TABLE OITM ADD COLUMN AssetItem TEXT DEFAULT 'N'; ALTER TABLE ORDR ADD COLUMN DocStatus TEXT DEFAULT 'O'; ALTER TABLE RDR1 ADD COLUMN WhsCode TEXT DEFAULT '01'; ALTER TABLE RDR1 ADD COLUMN Price REAL DEFAULT 500; INSERT INTO OACT VALUES('400000','Revenue');\");db.run(\"INSERT INTO OCRD VALUES ('C003','Delta Research','C'),('V002','Metro Chemicals','S'); INSERT INTO OITM(ItemCode,ItemName,OnHand) VALUES ('I003','Sample C',250),('I004','Sample D',80); INSERT INTO ORDR(DocEntry,DocNum,DocDate,CardCode,CardName,DocTotal,CANCELED,DocStatus) VALUES (3,1003,'2026-11-04','C003','Delta Research',6000,'N','O'),(4,1004,'2026-11-05','C001','Alpha Labs',4000,'N','O'); INSERT INTO RDR1(DocEntry,LineNum,ItemCode,Quantity,LineTotal,WhsCode,Price) VALUES(3,0,'I003',10,6000,'01',600),(4,0,'I004',8,4000,'01',500); INSERT INTO OITW VALUES('I002','01',50,5,20),('I003','01',250,10,0),('I004','01',80,8,0);\");status.textContent='Practice database ready';run.disabled=false;const picker=document.getElementById('sql-table');for(const row of db.exec(\"SELECT name FROM sqlite_master WHERE type='table' ORDER BY name\")[0].values){const opt=document.createElement('option');opt.value=row[0];opt.textContent=row[0];picker.append(opt);}picker.onchange=()=>{if(picker.value){editor.value='SELECT * FROM '+picker.value+';';run.click();}};}catch(e){status.textContent='Unable to load SQL engine: '+e.message;}run.onclick=()=>{out.replaceChildren();try{const q=editor.value.trim();if(!/^SELECT\\b/i.test(q)||q.replace(/;\\s*$/,'').includes(';'))throw Error('Enter one SELECT statement only.');const result=db.exec(q) ;for(const set of result){const table=document.createElement('table');table.style.cssText='width:100%;border-collapse:collapse';for(const row of [set.columns,...set.values.slice(0,200)]){const tr=table.insertRow();for(const value of row){const cell=tr.insertCell();cell.textContent=value===null?'NULL':String(value);cell.style.cssText='padding:10px;border:1px solid #cbd5e1';}}out.append(table);}status.textContent=result.length?result[0].values.length+' rows returned (display limit 200)':'No rows returned';}catch(e){status.textContent=e.message;}};</script>");
